function parseCents(value) {
  if (typeof value !== "string") return null;

  const text = value.trim();
  const match = /^([0-9]+)(?:\.([0-9]{1,2}))?$/.exec(text);
  if (!match) return null;

  const whole = match[1].replace(/^0+(?=\d)/, "");
  const fraction = match[2] === undefined
    ? "00"
    : match[2].length === 1
      ? match[2] + "0"
      : match[2];

  const centsText = (whole + fraction).replace(/^0+(?=\d)/, "");
  const maxText = String(Number.MAX_SAFE_INTEGER);

  if (
    centsText.length > maxText.length ||
    (centsText.length === maxText.length && centsText > maxText)
  ) {
    return null;
  }

  return Number(centsText);
}

